describe('Sidebar Collapse/Expand Functionality', () => {
  beforeEach(() => {
    cy.visit('/dashboard');
  });

  it('should collapse and expand sidebar on click', () => {
    // Verify sidebar is initially visible and expanded
    cy.get('[data-testid="sidebar"]').should('be.visible');
    cy.get('[data-testid="sidebar-menu-item"]').should('be.visible');
    cy.get('[data-testid="sidebar-toggle-button"]').should('be.visible');

    // Click to collapse sidebar
    cy.get('[data-testid="sidebar-toggle-button"]').click();

    // Verify sidebar is collapsed
    cy.get('[data-testid="sidebar"]').should('have.attr', 'data-collapsed', 'true');
    cy.get('[data-testid="sidebar-menu-item"]').should('not.exist');
    cy.get('[data-testid="sidebar-content"]').should('be.visible');

    // Click to expand sidebar
    cy.get('[data-testid="sidebar-toggle-button"]').click();

    // Verify sidebar is expanded
    cy.get('[data-testid="sidebar"]').should('not.have.attr', 'data-collapsed');
    cy.get('[data-testid="sidebar-menu-item"]').should('be.visible');
    cy.get('[data-testid="sidebar-content"]').should('be.visible');
  });

  it('should handle multiple clicks and maintain state', () => {
    // Verify sidebar is expanded
    cy.get('[data-testid="sidebar"]').should('not.have.attr', 'data-collapsed');

    // Collapse sidebar
    cy.get('[data-testid="sidebar-toggle-button"]').click();
    cy.get('[data-testid="sidebar"]').should('have.attr', 'data-collapsed', 'true');

    // Click again to expand
    cy.get('[data-testid="sidebar-toggle-button"]').click();
    cy.get('[data-testid="sidebar"]').should('not.have.attr', 'data-collapsed');

    // Click a third time to collapse
    cy.get('[data-testid="sidebar-toggle-button"]').click();
    cy.get('[data-testid="sidebar"]').should('have.attr', 'data-collapsed', 'true');

    // Verify sidebar toggle button text changes on each state change
    cy.get('[data-testid="sidebar-toggle-button"]').should('contain', 'Collapse');
    cy.get('[data-testid="sidebar-toggle-button"]').click();
    cy.get('[data-testid="sidebar-toggle-button"]').should('contain', 'Expand');
    cy.get('[data-testid="sidebar-toggle-button"]').click();
    cy.get('[data-testid="sidebar-toggle-button"]').should('contain', 'Collapse');
  });
});
